import{_ as s,C as o,o as r,c as n,j as e,a as i,E as h,a2 as l}from"./chunks/framework.BxGh02fV.js";const y=JSON.parse('{"title":"Tasks","description":"","frontmatter":{"title":"Tasks"},"headers":[],"relativePath":"en/guide/tasks.md","filePath":"en/guide/tasks.md"}'),d={name:"en/guide/tasks.md"};function c(g,t,u,f,k,p){const a=o("Capture");return r(),n("div",null,[t[0]||(t[0]=e("h1",{id:"tasks",tabindex:"-1"},[i("Tasks "),e("a",{class:"header-anchor",href:"#tasks","aria-label":'Permalink to "Tasks"'},"​")],-1)),t[1]||(t[1]=e("p",null,"This screen lists the tasks of the active story and lets you add new ones. You come here to follow the progress of the current work and to change the state of a task.",-1)),h(a,{name:"taches",alt:"The Tasks screen: three tasks of the active story and the New task form"}),t[2]||(t[2]=l('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>Tasks</strong> (left column): one card per task of the active story. <ul><li>The task reference (for example <code>26E2S1T1</code>), its state (<strong>To do</strong>, <strong>In progress</strong> or <strong>Done</strong>) and its OPALE phase (for example <code>O-analyse</code>).</li><li>The title in bold, then the description.</li><li>A drop-down list to change the state.</li></ul></li><li><strong>New task</strong> (right column): the form to add a task, with the <strong>Title</strong> and <strong>Description</strong> fields.</li></ul><p>If no story is active, the screen shows &quot;No active story&quot; and a <strong>Go to backlog</strong> button: activate a story from the <a href="/Effortless/en/guide/backlog.html">Backlog</a> first. If the story has no task yet, the list shows &quot;No task for this story.&quot;</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="change-the-state-of-a-task" tabindex="-1">Change the state of a task <a class="header-anchor" href="#change-the-state-of-a-task" aria-label="Permalink to &quot;Change the state of a task&quot;">​</a></h3><p>Open the drop-down list on the right of the card and pick <strong>To do</strong>, <strong>In progress</strong> or <strong>Done</strong>. The change is saved immediately and the list reloads. Set to <strong>In progress</strong> the task you are coding on: as long as at least one task of the project is <strong>In progress</strong>, the <a href="/Effortless/en/guide/drift.html">Drift</a> detector considers that there is an active task. It does not look at which one: keeping your task states accurate is up to you.</p><h3 id="add-a-task" tabindex="-1">Add a task <a class="header-anchor" href="#add-a-task" aria-label="Permalink to &quot;Add a task&quot;">​</a></h3><ol><li>Type a <strong>Title</strong>. It is required: nothing is created without one.</li><li>Optionally add a <strong>Description</strong>.</li><li>Click <strong>Add the task</strong>.</li></ol><p>The new task gets the story&#39;s current phase and appears in the list.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>A story can only be closed once all its tasks are <strong>Done</strong>.</li><li>If metadata auto-commit is on (see <a href="/Effortless/en/guide/git.html">Git</a>), every addition or state change is committed automatically.</li></ul><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>An agent does the same through the MCP server: <code>effortless_task_add</code> creates a task, <code>effortless_task_update</code> changes its state, and <code>effortless_story_items</code> lists the tasks of a story. The screen simply shows the result of their work.</p>',13))])}const T=s(d,[["render",c]]);export{y as __pageData,T as default};
